@namespace sv_f128e9c7b7ae4463bcd6c30004038ace.Components.Pages.Board

<div class="task-card">
    <h4 class="task-title">@Task.Title</h4>
    <p class="task-assignee">@Task.Assignee</p>
    <span class="priority-badge priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    <span class="task-due-date">@Task.DueDate.ToString("MMM dd")</span>
    <div class="task-actions">
        @if (CanMoveLeft)
        {
            <button class="btn-move-left" @onclick="OnMoveLeft">Move Left</button>
        }
        @if (CanMoveRight)
        {
            <button class="btn-move-right" @onclick="OnMoveRight">Move Right</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback OnMoveLeft { get; set; }
    [Parameter] public EventCallback OnMoveRight { get; set; }
}

@namespace sv_f128e9c7b7ae4463bcd6c30004038ace.Components.Pages.Board

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="title" />
    <input type="text" placeholder="Assignee" @bind="assignee" />
    <select @bind="priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" />
    <div class="form-actions">
        <button class="btn-save" @onclick="HandleSave">Save</button>
        <button class="btn-cancel" @onclick="OnCancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnSave { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);

    private async Task HandleSave()
    {
        if (!string.IsNullOrWhiteSpace(title))
        {
            await OnSave.InvokeAsync((title, assignee, priority, dueDate));
            title = string.Empty;
            assignee = string.Empty;
            priority = "Medium";
            dueDate = DateTime.Today.AddDays(7);
        }
    }
}

@namespace sv_f128e9c7b7ae4463bcd6c30004038ace.Components.Pages.Board

<div class="kanban-column">
    <div class="column-header">
        <h3>@ColumnName (@Tasks.Count)</h3>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      OnMoveLeft="() => OnMoveTask.InvokeAsync((task.Id, MoveDirection.Left))"
                      OnMoveRight="() => OnMoveTask.InvokeAsync((task.Id, MoveDirection.Right))" />
        }
    </div>
    @if (showForm)
    {
        <AddTaskForm OnSave="HandleAdd" OnCancel="() => showForm = false" />
    }
    else
    {
        <button class="btn-add-task" @onclick="() => showForm = true">Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = string.Empty;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<(int TaskId, MoveDirection Direction)> OnMoveTask { get; set; }
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate, string Status)> OnAddTask { get; set; }

    private bool showForm;

    private async Task HandleAdd((string Title, string Assignee, string Priority, DateTime DueDate) formData)
    {
        await OnAddTask.InvokeAsync((formData.Title, formData.Assignee, formData.Priority, formData.DueDate, ColumnName));
        showForm = false;
    }
}

public enum MoveDirection { Left, Right }

@namespace sv_f128e9c7b7ae4463bcd6c30004038ace.Components.Pages.Board

<div class="board-stats-bar">
    <span class="stat-item">Total: @TotalCount</span>
    <span class="stat-item">To Do: @ToDoCount</span>
    <span class="stat-item">In Progress: @InProgressCount</span>
    <span class="stat-item">Done: @DoneCount</span>
    <span class="stat-item stat-overdue">Overdue: @OverdueCount</span>
</div>

@code {
    [Parameter] public int TotalCount { get; set; }
    [Parameter] public int ToDoCount { get; set; }
    [Parameter] public int InProgressCount { get; set; }
    [Parameter] public int DoneCount { get; set; }
    [Parameter] public int OverdueCount { get; set; }
}

@namespace sv_f128e9c7b7ae4463bcd6c30004038ace.Components.Pages.Board

<div class="board-search-bar">
    <input type="text" placeholder="Search tasks by title..." value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> OnSearchChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        await OnSearchChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    }
}

@page "/board"
@namespace sv_f128e9c7b7ae4463bcd6c30004038ace.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

@if (isLoading)
{
    <p class="loading-message">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error-message">@errorMessage</p>
}
else
{
    <BoardStatsBar TotalCount="allTasks.Count"
                   ToDoCount="GetTasksForStatus("To Do").Count"
                   InProgressCount="GetTasksForStatus("In Progress").Count"
                   DoneCount="GetTasksForStatus("Done").Count"
                   OverdueCount="allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="kanban-columns">
        <KanbanColumn ColumnName="To Do"
                      Tasks="GetFilteredTasksForStatus("To Do")"
                      CanMoveLeft="false"
                      CanMoveRight="true"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="HandleAddTask" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="GetFilteredTasksForStatus("In Progress")"
                      CanMoveLeft="true"
                      CanMoveRight="true"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="HandleAddTask" />

        <KanbanColumn ColumnName="Done"
                      Tasks="GetFilteredTasksForStatus("Done")"
                      CanMoveLeft="true"
                      CanMoveRight="false"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="HandleAddTask" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Columns = { "To Do", "In Progress", "Done" };

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetTasksForStatus(string status) =>
        allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredTasksForStatus(string status) =>
        allTasks
            .Where(t => t.Status == status)
            .Where(t => string.IsNullOrEmpty(searchText) ||
                        t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase))
            .ToList();

    private void HandleSearchChanged(string text)
    {
        searchText = text;
    }

    private async Task HandleMoveTask((int TaskId, MoveDirection Direction) move)
    {
        var task = allTasks.FirstOrDefault(t => t.Id == move.TaskId);
        if (task is null) return;

        var currentIndex = Array.IndexOf(Columns, task.Status);
        var newIndex = move.Direction == MoveDirection.Left ? currentIndex - 1 : currentIndex + 1;

        if (newIndex < 0 || newIndex >= Columns.Length) return;

        var newStatus = Columns[newIndex];

        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            allTasks[index] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleAddTask((string Title, string Assignee, string Priority, DateTime DueDate, string Status) data)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
            allTasks.Add(newTask with { Status = data.Status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to add task: {ex.Message}";
        }
    }
}

