.board-stats-bar {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
    margin-bottom: 1rem;
}

.stat-item {
    font-weight: 600;
}

.stat-overdue {
    color: #dc3545;
}

.board-search-bar {
    margin-bottom: 1rem;
}

.board-search-bar input {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
}

.kanban-columns {
    display: flex;
    gap: 1rem;
}

.kanban-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 0.5rem;
    padding: 1rem;
    min-height: 400px;
    display: flex;
    flex-direction: column;
}

.column-header h3 {
    margin: 0 0 1rem 0;
    font-size: 1.1rem;
}

.column-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    padding: 0.75rem;
}

.task-title {
    margin: 0 0 0.25rem 0;
    font-size: 0.95rem;
}

.task-assignee {
    margin: 0 0 0.5rem 0;
    color: #6c757d;
    font-size: 0.85rem;
}

.priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 0.25rem;
    font-size: 0.75rem;
    font-weight: 600;
    margin-right: 0.5rem;
}

.priority-high {
    background: #dc3545;
    color: #fff;
}

.priority-medium {
    background: #ffc107;
